 a=ans[q['id']];assert q['version']==a['questionVersion'];assert set(q['correctOptionIds'])==set(a['independentAnswerOptionIds']);n=int(q['id'].split('-Q')[1]);f=flags.get(n,{})
 reasoning=a['reasoning']+' All 25 source page images were inspected and source-derived answers plus executable checks frozen before author keys or solution access. The complete key agrees. All nine dimensions were subsequently compared with source pixels, assumptions, all individual option rationales, calculation steps and formula metadata. Code/math checks passed 34 named assertions, 1,000 independent nearest-neighbor queries and 1,000 objective-ordering cases. '+('The listed quality findings prevent approval of this version; no key correction is required.' if f else 'Source support, assumptions, full answer set, distractors, calculations, figure fidelity, explanation, difficulty and nonduplication pass for this version. No nontrivial calculation or separate figure inference is claimed where not applicable.')
 reviews.append({'id':f'REV-{q["id"]}-v{q["version"]}-independent-interface','questionId':q['id'],'questionVersion':q['version'],'questionSha256':question_hash(q),'reviewerId':AUTHOR,'decision':'flagged' if f else 'verified','reviewedAt':now,'sourceVersions':{c['sourceId']:c['sourceSha256'] for c in q['citations']},'reviewedSlideIds':list(dict.fromkeys(c['slideId'] for c in q['citations'])),'independentAnswerOptionIds':a['independentAnswerOptionIds'],'solvedBeforeAnswerSeen':True,'checks':{k:k not in f for k in CHECK_KEYS},'reasoning':reasoning,'findings':[f'{k}: {v}' for k,v in f.items()]})
